 contract=read(E/'contract/contrato_comparabilidade.json');assert sha(E/'contract/contrato_comparabilidade.json')==read(A/'baseline.json')['W28ContractSHA256'];rows=[];redundancy={'23':('58','O mesmo campo Censo de ausência de abastecimento já é mostrado na Q58. A pergunta diária permanece distinta e não foi visualizada.'),'76':('81','O indicador Censo de existência de banheiro já é mostrado na Q81; ele não mede separação por gênero.'),'83':('81','O indicador Censo de existência de banheiro já é mostrado na Q81; ele não mede privacidade/portas/trancas.'),'105':('81/98','Os componentes Censo banheiro/chuveiro já são mostrados em Q81/Q98 e não representam a condição composta de higiene e segurança da Q105.')}
 for q in contract['rows']:
  n=q['question'];partial=q['semanticClassification']=='Parcial/complementar';implemented=q['enabledInPilot'];missing=[v['field']for v in q['censusItems']if not v['availableInAdoptedFact']]
